/**
 * useMonitorActivity — Monitor Dashboard "Recent Activity" feed state
 * (ticket #1129).
 *
 * Fetches the feed on mount. A discriminated union — never a
 * loading/error/data object with optional fields — so the card can switch
 * exhaustively:
 *   - "loading" while the initial fetch is in flight
 *   - "data" once monitorDashboardActivity() resolves (an EMPTY feed is
 *     status:"data" with items:[], NEVER inferred from a failed fetch)
 *   - "error" on any fetch failure; carries `retry()` to re-fetch in place
 *
 * Mirrors useMonitorDashboardStats: the hook's RETURN VALUE is the
 * discriminated union itself (no separate `{ state, refetch }` wrapper), and
 * `retry` lives on the "error" variant.
 */

import { useCallback, useEffect, useState } from "react";
import {
  type MonitorActivityItem,
  monitorDashboardActivity,
} from "../api/activity";

export type MonitorActivityState =
  | { readonly status: "loading" }
  | { readonly status: "data"; readonly items: readonly MonitorActivityItem[] }
  | { readonly status: "error"; readonly retry: () => void };

/**
 * useMonitorActivity — fetches the feed on mount.
 *
 * "loading" while the fetch is in flight, "data" on success (carrying the
 * mapped, newest-first items), "error" (carrying `retry`) on any failure.
 * `retry` re-runs the load in place — it does not flash back to "loading"
 * first, so a failed retry that succeeds transitions straight from "error" to
 * "data".
 *
 * The mount fetch is aborted on unmount via the AbortController threaded into
 * monitorDashboardActivity(); the abort rejection is the normal teardown path,
 * never a real fetch failure, so it must never surface as status:"error".
 */
export function useMonitorActivity(): MonitorActivityState {
  const [state, setState] = useState<MonitorActivityState>({
    status: "loading",
  });

  const load = useCallback((): AbortController => {
    const controller = new AbortController();
    void monitorDashboardActivity(controller.signal)
      .then((items) => {
        setState({ status: "data", items });
      })
      .catch((err: unknown) => {
        // The effect-cleanup abort() on unmount rejects this same promise —
        // normal teardown, not a real failure. Guard on the controller's own
        // signal first (authoritative), falling back to the error's name.
        if (
          controller.signal.aborted ||
          (err instanceof Error && err.name === "AbortError")
        ) {
          return;
        }
        setState({ status: "error", retry: load });
      });
    return controller;
  }, []);

  useEffect(() => {
    const controller = load();
    return () => {
      controller.abort();
    };
  }, [load]);

  return state;
}


