/**
 * useNewsCoverage — the standing GDELT article volume for the Home
 * CoverageStrip's GDELT chip (ticket #1138).
 *
 * On mount it asks GET /api/v1/monitor/news/coverage for a recent-article
 * count. Three states: "loading" (probe in flight), "ready" (resolved, carrying
 * `articleCount` — a zero is a legitimate honest value, not an error), and
 * "error" (any failure). The consuming card renders the honest-empty coverage
 * line while loading, on error, or when the count is zero — it never fabricates
 * a volume.
 *
 * The probe aborts on unmount and every settle guards on its own controller, so
 * a late response never reaches setState. The hook never throws during render:
 * every failure is caught into the "error" state.
 */

import { useEffect, useRef, useState } from "react";
import { getNewsCoverage } from "../api/news";

/** The coverage probe discriminant. */
export type NewsCoverageState =
  | { readonly state: "loading" }
  | { readonly state: "ready"; readonly articleCount: number }
  | { readonly state: "error" };

export function useNewsCoverage(): NewsCoverageState {
  const [state, setState] = useState<NewsCoverageState>({ state: "loading" });

  // The in-flight probe; the effect cleanup aborts it on unmount.
  const controllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    controllerRef.current = controller;

    void getNewsCoverage(controller.signal)
      .then((coverage) => {
        if (controller.signal.aborted) return;
        setState({ state: "ready", articleCount: coverage.articleCount });
      })
      .catch((err: unknown) => {
        // A cancellation (unmount) rejects this same promise — normal teardown.
        if (
          controller.signal.aborted ||
          (err instanceof Error && err.name === "AbortError")
        ) {
          return;
        }
        setState({ state: "error" });
      });

    return () => {
      controller.abort();
    };
  }, []);

  return state;
}


--- frontends/monitor-mfe/src/hooks/useNewsSearch.ts (227 lines) ---
/**
 * useNewsSearch — News-source (GDELT) search for the Monitor Search surface.
 *
 * #1133 shipped this as an honestly-idle stub (the discriminated-union
 * contract only, no backend). #1138 reworks the BODY to a real, SUBMIT-
 * triggered fetch against POST /api/v1/monitor/news, mirroring useWebSearch
 * (see that hook's header for the abort/overlap/error-never-throws rationale)
 * with ONE News-only addition: the Retry-After live countdown.
 *
 * It starts "idle" and only moves once the user triggers `run(query)`. A single
 * `controllerRef` always points at the newest in-flight request — each run()
 * aborts the prior controller first (so an overlapping search cancels the one
 * still in flight and only the newest response wins), the effect cleanup aborts
 * it on unmount, and every settle handler bails when its own controller is
 * aborted, so a stale/cancelled response never reaches setState and an
 * AbortError never surfaces as an error state.
 *
 * The error state carries `kind`: a MonitorApiError with status 429 maps to
 * "throttle" (GDELT is rate-limiting — informational, auto-retryable), every
 * other failure (503, other statuses, network) maps to "unavailable". When a
 * throttle carries a `Retry-After` (surfaced on MonitorApiError.retryAfter), the
 * error state also carries a LIVE countdown: `retryAfter` ticks from that many
 * seconds down toward 1, and the hook AUTO-REPLAYS the same query the moment it
 * reaches zero. A throttle with no Retry-After has no countdown (`retryAfter`
 * undefined) and recovers via the manual `retry()` only.
 *
 * Per-source independence (#1133 AC): this hook shares SearchRoute with the Web
 * and Range hooks, so it MUST catch every failure and return {state:"error"} —
 * it never throws during render, so a News failure can never blank or crash the
 * other panes.
 *
 * The raw server `message` is deliberately NOT surfaced: the UI shows generic,
 * non-leaking copy for every failure.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import {
  executeNewsSearch,
  type NewsResult,
  type NewsSearchOptions,
} from "../api/news";
import { MonitorApiError } from "../api/client";

/** Which flavor of failure the error state represents. */
export type NewsSearchErrorKind = "throttle" | "unavailable";

/** The submit-driven discriminant, before the shared controls are layered on. */
type NewsSearchCore =
  | { readonly state: "idle" }
  | { readonly state: "loading" }
  | { readonly state: "data"; readonly results: NewsResult[] }
  | {
      readonly state: "error";
      readonly kind: NewsSearchErrorKind;
      /**
       * Seconds remaining in the live retry countdown — present ONLY for a
       * throttle that carried a Retry-After. It ticks from the server's
       * Retry-After value down to 1; the hook then auto-replays the query.
       * `undefined` = no countdown (a non-throttle failure, or a throttle with
       * no Retry-After) — recovery is the manual `retry()` only.
       */
      readonly retryAfter?: number;
      /** Re-run the last query in place — the error state's recovery action. */
      readonly retry: () => void;
    };

/** Controls available on EVERY state (mirrors useWebSearch). */
export interface NewsSearchControls {
  /**
   * Trigger a News search for `query`, optionally scoped by filter/country/
   * locale `options`; supersedes any in-flight run. The options are captured so
   * `retry()` (and the countdown's auto-replay) replay the exact same request.
   */
  readonly run: (query: string, options?: NewsSearchOptions) => void;
  /** Return to the "idle" empty state, cancelling any in-flight run/countdown. */
  readonly reset: () => void;
}

export type NewsSearchState = NewsSearchCore & NewsSearchControls;

/** Map a thrown error into the error-state's `kind`. */
function kindForError(err: unknown): NewsSearchErrorKind {
  return err instanceof MonitorApiError && err.status === 429
    ? "throttle"
    : "unavailable";
}

export function useNewsSearch(): NewsSearchState {
  const [state, setState] = useState<NewsSearchCore>({ state: "idle" });

  // The newest in-flight request; every run() aborts whatever this points at
  // before replacing it, and the effect cleanup aborts it on unmount.
  const controllerRef = useRef<AbortController | null>(null);
  // The last request (query + its options), so retry() and the countdown's
  // auto-replay re-run it with the IDENTICAL filters/country/locale.
  const lastQueryRef = useRef<{
    query: string;
    options: NewsSearchOptions | undefined;
  } | null>(null);

  // The live Retry-After countdown interval (null = none running). Cleared on
  // every new run(), reset(), and unmount so a stale timer never ticks against
  // a superseded search or a torn-down component.
  const countdownRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // retry()/run() held in refs so the error variant's `retry`, and the
  // countdown's auto-replay, are stable references reachable from a settle
  // handler or an interval callback without a dependency cycle.
  const retryRef = useRef<() => void>(() => undefined);
  const runRef = useRef<(query: string, options?: NewsSearchOptions) => void>(
    () => undefined,
  );

  const clearCountdown = useCallback((): void => {
    if (countdownRef.current !== null) {
      clearInterval(countdownRef.current);
      countdownRef.current = null;
    }
  }, []);

  // Start the live Retry-After countdown from `seconds`. Each tick decrements
  // the visible `retryAfter`; when it reaches zero the timer is cleared and the
  // last query is auto-replayed. The functional setState only rewrites a still-
  // throttle error state, so a race with a reset/new-run can never resurrect a
  // stale countdown value.
  const startCountdown = useCallback(
    (seconds: number): void => {
      clearCountdown();
      let remaining = seconds;
      countdownRef.current = setInterval(() => {
        remaining -= 1;
        if (remaining <= 0) {
          clearCountdown();
          const last = lastQueryRef.current;
          if (last !== null) runRef.current(last.query, last.options);
          return;
        }
        setState((prev) =>
          prev.state === "error" && prev.kind === "throttle"
            ? { ...prev, retryAfter: remaining }
            : prev,
        );
      }, 1000);
    },
    [clearCountdown],
  );

  const run = useCallback(
    (query: string, options?: NewsSearchOptions): void => {
      lastQueryRef.current = { query, options };

      // Cancel any request still in flight and any running countdown so an
      // overlapping run wins and no stale timer survives.
      controllerRef.current?.abort();
      clearCountdown();
      const controller = new AbortController();
      controllerRef.current = controller;

      setState({ state: "loading" });

      void executeNewsSearch(query, options, controller.signal)
        .then((response) => {
          if (controller.signal.aborted) return;
          setState({ state: "data", results: response.results });
        })
        .catch((err: unknown) => {
          // A cancellation (overlapping run or unmount) rejects this same
          // promise — normal teardown, never a real failure.
          if (
            controller.signal.aborted ||
            (err instanceof Error && err.name === "AbortError")
          ) {
            return;
          }
          const kind = kindForError(err);
          // A throttle carrying a positive Retry-After drives the live
          // countdown; anything else recovers via the manual retry() only.
          const retryAfter =
            kind === "throttle" &&
            err instanceof MonitorApiError &&
            err.retryAfter !== undefined &&
            err.retryAfter > 0
              ? err.retryAfter
              : undefined;
          setState({
            state: "error",
            kind,
            retryAfter,
            retry: retryRef.current,
          });
          if (retryAfter !== undefined) startCountdown(retryAfter);
        });
    },
    [clearCountdown, startCountdown],
  );

  const retry = useCallback((): void => {
    const last = lastQueryRef.current;
    if (last !== null) run(last.query, last.options);
  }, [run]);

  // Point the refs at the current callbacks. Done in effects so render stays
  // pure; a settle handler / interval reads them only after these effects run.
  useEffect(() => {
    retryRef.current = retry;
  }, [retry]);
  useEffect(() => {
    runRef.current = run;
  }, [run]);

  const reset = useCallback((): void => {
    controllerRef.current?.abort();
    controllerRef.current = null;
    clearCountdown();
    setState({ state: "idle" });
  }, [clearCountdown]);

  useEffect(() => {
    return () => {
      controllerRef.current?.abort();
      clearCountdown();
    };
  }, [clearCountdown]);

  return { ...state, run, reset };
}


--- frontends/monitor-mfe/src/hooks/usePosts.ts (66 lines) ---
/**
 * usePosts — the user's tracked-posts list state for the Posts surface (#1171).
 * Fetches the list on mount. An empty list is status:"data" with posts:[] (the
 * honest empty state a fresh workspace shows), never inferred from a failure.
 *
 * Mirrors useTrends: the hook's RETURN VALUE is a discriminated union, and every
 * variant (loading / data / error) carries the SAME stable `reload()` callback,
 * so a caller can re-run the load from any state — including recovering from an
 * error. `reload()` aborts any in-flight fetch and starts a fresh one. The mount
 * fetch (and any reload) is aborted on unmount — a normal teardown, never an
 * error.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { type TrackedPost, listTrackedPosts } from "../api/posts";

type PostsCore =
  | { readonly status: "loading" }
  | { readonly status: "data"; readonly posts: readonly TrackedPost[] }
  | { readonly status: "error" };

export type PostsState = (
  | { readonly status: "loading" }
  | { readonly status: "data"; readonly posts: readonly TrackedPost[] }
  | { readonly status: "error" }
) & { readonly reload: () => void };

export function usePosts(): PostsState {
