 * "forbidden" state (a monitor user who isn't an exercise member), not a hard
 * error. `retry` on "error" re-runs the load. The load is aborted on unmount /
 * when disabled — a normal teardown, never surfaced as an error.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { MonitorApiError } from "../api/client";
import { type RangeExercise, listRangeExercises } from "../api/rangeExercises";

type RangeExercisesCore =
  | { readonly status: "loading" }
  | { readonly status: "data"; readonly exercises: readonly RangeExercise[] }
  | { readonly status: "forbidden" }
  | { readonly status: "error" };

export type RangeExercisesState =
  | { readonly status: "loading" }
  | { readonly status: "data"; readonly exercises: readonly RangeExercise[] }
  | { readonly status: "forbidden" }
  | { readonly status: "error"; readonly retry: () => void };

export function useRangeExercises(enabled: boolean): RangeExercisesState {
  const [core, setCore] = useState<RangeExercisesCore>({ status: "loading" });
  const controllerRef = useRef<AbortController | null>(null);

  const load = useCallback((): void => {
    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;

    void listRangeExercises(controller.signal)
      .then((exercises) => {
        if (controller.signal.aborted) return;
        setCore({ status: "data", exercises });
      })
      .catch((err: unknown) => {
        if (
          controller.signal.aborted ||
          (err instanceof Error && err.name === "AbortError")
        ) {
          return;
        }
        if (err instanceof MonitorApiError && err.status === 403) {
          setCore({ status: "forbidden" });
          return;
        }
        setCore({ status: "error" });
      });
  }, []);

  useEffect(() => {
    if (!enabled) return;
    load();
    return () => controllerRef.current?.abort();
  }, [enabled, load]);

  if (core.status === "error") {
    return { status: "error", retry: load };
