/**
 * useSavedSearches — the Saved Queries rail's list state (#1136 / #1137).
 *
 * Fetches the user's saved searches on mount. An empty list is status:"data"
 * with searches:[] (the rail's empty state), never inferred from a failure.
 * Every variant carries the same stable `reload()` so a caller can re-run the
 * load from any state, including error recovery.
 *
 * The `data` variant additionally exposes the four mutation ops the modal + rail
 * drive: create / update / remove / recordExecution. Each awaits the API call,
 * then reconciles the LOCAL list (prepend / replace / drop) so the rail reflects
 * the change without a full refetch, and RE-THROWS on failure so the caller can
 * surface an inline error. A failed mutation never mutates the list.
 *
 * Race safety: reload() aborts any in-flight load and bumps a generation counter
 * (a result whose captured generation != current is discarded), and the mount
 * fetch is aborted on unmount — a normal teardown, never an error.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import {
  type SavedSearch,
  type SavedSearchInput,
  buildSavedSearchCreateBody,
  buildSavedSearchUpdateBody,
  createSavedSearch,
  deleteSavedSearch,
  listSavedSearches,
  recordSavedSearchExecution,
  updateSavedSearch,
} from "../api/search";

type Core =
  | { readonly status: "loading" }
  | { readonly status: "data"; readonly searches: readonly SavedSearch[] }
  | { readonly status: "error" };

interface Ops {
  readonly reload: () => void;
  readonly create: (input: SavedSearchInput) => Promise<SavedSearch>;
  readonly update: (id: string, input: SavedSearchInput) => Promise<SavedSearch>;
  readonly remove: (id: string) => Promise<void>;
  readonly recordExecution: (id: string) => Promise<SavedSearch>;
}

export type SavedSearchesState = (
  | { readonly status: "loading" }
  | { readonly status: "data"; readonly searches: readonly SavedSearch[] }
  | { readonly status: "error" }
) &
  Ops;

function isAbort(err: unknown): boolean {
  return err instanceof Error && err.name === "AbortError";
}

export function useSavedSearches(): SavedSearchesState {
  const [core, setCore] = useState<Core>({ status: "loading" });
  const controllerRef = useRef<AbortController | null>(null);
  const genRef = useRef(0);

  const load = useCallback((): void => {
    controllerRef.current?.abort();
    const gen = ++genRef.current;
    const controller = new AbortController();
    controllerRef.current = controller;
    setCore({ status: "loading" });

    void listSavedSearches(controller.signal)
      .then((searches) => {
        if (controller.signal.aborted || gen !== genRef.current) return;
        setCore({ status: "data", searches });
      })
      .catch((err: unknown) => {
        if (controller.signal.aborted || gen !== genRef.current || isAbort(err)) {
          return;
        }
        setCore({ status: "error" });
      });
  }, []);

  useEffect(() => {
    load();
    return () => controllerRef.current?.abort();
  }, [load]);

  // Reconcile the local list after a successful mutation. A no-op when the hook
  // isn't in the data state (a mutation can only be triggered from the rail,
  // which only renders in the data state — but the guard keeps state honest).
  const reconcile = useCallback(
    (fn: (prev: readonly SavedSearch[]) => readonly SavedSearch[]): void => {
      setCore((prev) =>
        prev.status === "data" ? { status: "data", searches: fn(prev.searches) } : prev,
      );
    },
    [],
  );

  const create = useCallback(
    async (input: SavedSearchInput): Promise<SavedSearch> => {
      const created = await createSavedSearch(buildSavedSearchCreateBody(input));
      reconcile((prev) => [created, ...prev]);
      return created;
    },
    [reconcile],
  );

  const update = useCallback(
    async (id: string, input: SavedSearchInput): Promise<SavedSearch> => {
      const updated = await updateSavedSearch(id, buildSavedSearchUpdateBody(input));
      reconcile((prev) => prev.map((s) => (s.id === id ? updated : s)));
      return updated;
    },
    [reconcile],
  );

  const remove = useCallback(
    async (id: string): Promise<void> => {
      await deleteSavedSearch(id);
      reconcile((prev) => prev.filter((s) => s.id !== id));
    },
    [reconcile],
  );

  const recordExecution = useCallback(
    async (id: string): Promise<SavedSearch> => {
      const updated = await recordSavedSearchExecution(id);
      reconcile((prev) => prev.map((s) => (s.id === id ? updated : s)));
      return updated;
    },
    [reconcile],
  );

  const ops: Ops = { reload: load, create, update, remove, recordExecution };

  if (core.status === "data") {
    return { status: "data", searches: core.searches, ...ops };
  }
  if (core.status === "error") {
    return { status: "error", ...ops };
  }
  return { status: "loading", ...ops };
}


