/**
 * useSearchProviders — proactive web-search provider availability (#1134).
 *
 * On mount it asks GET /api/v1/monitor/search/providers whether a Serper key is
 * configured, so the Search surface can render its "unavailable" state BEFORE
 * the user runs a search (rather than only reactively, after a failed query).
 *
 * Two states: "checking" (the probe is in flight) and "ready" (resolved, with
 * `serperAvailable`). The probe is optimistic on failure: any error — a
 * transient store blip, a non-2xx, a network drop — resolves to
 * `serperAvailable: true`, so a probe hiccup never blocks the user out of
 * searching; the reactive useWebSearch error path still catches a truly
 * unconfigured provider when the query actually runs.
 *
 * `recheck()` re-runs the probe in place (the unavailable pane's "Try again"),
 * aborting any prior in-flight probe first; the effect cleanup aborts on
 * unmount, and every settle guards on its own controller so a stale response
 * never reaches setState.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { getSearchProviders } from "../api/search";

/** The probe discriminant. */
type SearchProvidersCore =
  | { readonly state: "checking" }
  | { readonly state: "ready"; readonly serperAvailable: boolean };

export interface SearchProvidersControls {
  /** Re-run the availability probe in place (supersedes any in-flight probe). */
  readonly recheck: () => void;
}

export type SearchProvidersState = SearchProvidersCore & SearchProvidersControls;

export function useSearchProviders(): SearchProvidersState {
  const [state, setState] = useState<SearchProvidersCore>({ state: "checking" });

  // The newest in-flight probe; recheck() aborts whatever this points at before
  // replacing it, and the effect cleanup aborts it on unmount.
  const controllerRef = useRef<AbortController | null>(null);

  const probe = useCallback((): void => {
    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;

    setState({ state: "checking" });

    void getSearchProviders(controller.signal)
      .then((providers) => {
        if (controller.signal.aborted) return;
        setState({ state: "ready", serperAvailable: providers.serperAvailable });
      })
      .catch((err: unknown) => {
        // A cancellation (recheck or unmount) rejects this same promise — normal
        // teardown, never a real signal.
        if (
          controller.signal.aborted ||
          (err instanceof Error && err.name === "AbortError")
        ) {
          return;
        }
        // Optimistic on any real error: assume available so a probe blip never
        // locks the user out — the reactive search path still surfaces a truly
        // unconfigured provider when the query runs.
        setState({ state: "ready", serperAvailable: true });
      });
  }, []);

  useEffect(() => {
    probe();
    return () => {
      controllerRef.current?.abort();
    };
  }, [probe]);

  return { ...state, recheck: probe };
}


