/**
 * useTranslate — Translate submit state (ticket #1157).
 *
 * A SUBMIT-triggered hook mirroring useSummarize: it starts "idle" and only
 * moves once the caller triggers `run()`. A discriminated union so the panel can
 * switch exhaustively:
 *   - "idle"    before any translate (the panel is not rendered)
 *   - "loading" while a translation is in flight (skeleton + "Translating…")
 *   - "data"    once translateContent() resolves (carries the translated markdown)
 *   - "error"   on any failure; carries `retry()` to re-run the last translate
 *
 * `run(markdown, targetLocale)` triggers a translate; `reset()` returns to
 * "idle"; `retry()` re-runs the LAST (markdown, targetLocale). All three are
 * layered onto every state at the return boundary so a caller that has narrowed
 * `status` can still reach them.
 *
 * A single `controllerRef` always points at the newest in-flight request: each
 * run() aborts the prior controller first (so an overlapping translate — e.g.
 * switching target mid-flight — cancels the one still in flight and only the
 * newest response wins), the effect cleanup aborts it on unmount, and every
 * settle handler bails when its own controller is aborted — so a stale/cancelled
 * response never reaches setState and an AbortError never surfaces as
 * status:"error".
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { translateContent } from "../api/translate";

/** The load-driven discriminant, before the shared controls are layered on. */
type TranslateCore =
  | { readonly status: "idle" }
  | { readonly status: "loading" }
  | { readonly status: "data"; readonly translated: string }
  | { readonly status: "error"; readonly retry: () => void };

/** Controls available on EVERY state (see useSummarize). */
export interface TranslateControls {
  /** Translate `markdown` into `targetLocale`; supersedes any in-flight run. */
  readonly run: (markdown: string, targetLocale: string) => void;
  /** Return to the "idle" state, cancelling any in-flight run. */
  readonly reset: () => void;
  /**
   * Re-run the LAST translate (same markdown + targetLocale). Semantically the
   * error state's recovery action — also exposed on every state so a caller that
   * has already narrowed `status === "error"` can invoke it from a deferred
   * callback where the discriminant no longer narrows.
   */
  readonly retry: () => void;
}

export type MonitorTranslateState = TranslateCore & TranslateControls;

export function useTranslate(): MonitorTranslateState {
  const [state, setState] = useState<TranslateCore>({ status: "idle" });

  // The newest in-flight request; every run() aborts whatever this points at
  // before replacing it, and the effect cleanup aborts it on unmount.
  const controllerRef = useRef<AbortController | null>(null);
  // The last requested (markdown, targetLocale), so retry() can re-run it.
  const lastRequestRef = useRef<{
    markdown: string;
    targetLocale: string;
  } | null>(null);

  const run = useCallback((markdown: string, targetLocale: string): void => {
    lastRequestRef.current = { markdown, targetLocale };

    // Cancel any request still in flight so an overlapping run wins and its
    // stale predecessor is dropped by the aborted-signal guards below.
    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;

    setState({ status: "loading" });

    void translateContent(markdown, targetLocale, controller.signal)
      .then((translated) => {
        // A newer run (or unmount) aborted this one — drop the stale response.
        if (controller.signal.aborted) return;
        setState({ status: "data", translated });
      })
      .catch((err: unknown) => {
        // A cancellation (overlapping run or unmount) rejects this same promise
        // — normal teardown, never a real failure, so it must not surface as
        // status:"error". Guard on the controller's own signal first
        // (authoritative), falling back to the error's name.
        if (
          controller.signal.aborted ||
          (err instanceof Error && err.name === "AbortError")
        ) {
          return;
        }
        setState({ status: "error", retry: retryRef.current });
      });
  }, []);

  // retry() re-runs the last translate. Held in a ref so the error variant's
  // `retry` is a stable reference and run()'s catch can reference it without a
  // dependency cycle.
  const retryRef = useRef<() => void>(() => undefined);
  const retry = useCallback((): void => {
    const last = lastRequestRef.current;
    if (last) run(last.markdown, last.targetLocale);
  }, [run]);
  retryRef.current = retry;

  const reset = useCallback((): void => {
    // Cancel any in-flight translate so its late response can't clobber idle.
    controllerRef.current?.abort();
    controllerRef.current = null;
    setState({ status: "idle" });
  }, []);

  useEffect(() => {
    return () => {
      controllerRef.current?.abort();
    };
  }, []);

  return { ...state, run, reset, retry };
}


