/**
 * useTrends — the user's trend-monitor list state for the Trends surface
 * (#1143 / #2288). Fetches the first page on mount. An empty list is
 * status:"data" with monitors:[] (the prompt-to-create empty state), never
 * inferred from a failure.
 *
 * Discriminated union: the hook's RETURN VALUE is the union itself. Every
 * variant (loading / data / error) carries the SAME stable `reload()` callback,
 * so a caller can re-run the load from any state — including while the initial
 * request is still in flight. `reload()` aborts any in-flight fetch and starts a
 * fresh page-1 load; this matters after a create, because a create completing
 * mid-load would otherwise let the initial request resolve with a pre-create
 * snapshot and drop the new monitor.
 *
 * The `data` variant also carries paging: `nextPageToken` ("" ⇒ no more pages),
 * `loadingMore`, and a stable `loadMore()` that fetches the next page and
 * APPENDS it (dedup by id). `loadMore()` no-ops when the status isn't "data",
 * the token is "", or a page load is already in flight.
 *
 * Race safety: a `reload()` resets to page 1 and must win over any in-flight
 * `loadMore` — a slow page-2 response must not append onto the freshly-reloaded
 * list. Two guards enforce this: (1) a generation counter bumped on every
 * reload (a result whose captured generation != current is discarded), and
 * (2) AbortControllers (reload aborts the in-flight loadMore). The mount fetch
 * (and any reload/loadMore) is aborted on unmount — a normal teardown, never an
 * error.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { type TrendMonitor, listTrendMonitors } from "../api/trends";

type TrendsCore =
  | { readonly status: "loading" }
  | {
      readonly status: "data";
      readonly monitors: readonly TrendMonitor[];
      readonly nextPageToken: string;
    }
  | { readonly status: "error" };

export type TrendsState = (
  | { readonly status: "loading" }
  | {
      readonly status: "data";
      readonly monitors: readonly TrendMonitor[];
      readonly nextPageToken: string;
      readonly loadingMore: boolean;
      readonly loadMore: () => void;
    }
  | { readonly status: "error" }
) & { readonly reload: () => void };

function isAbort(err: unknown): boolean {
  return err instanceof Error && err.name === "AbortError";
}

export function useTrends(): TrendsState {
  const [core, setCore] = useState<TrendsCore>({ status: "loading" });
  const [loadingMore, setLoadingMore] = useState(false);

  // Latest core mirrored into a ref so the stable loadMore() callback can read
  // the current token/list without being re-created on every render.
  const coreRef = useRef<TrendsCore>(core);
  coreRef.current = core;
  const loadingMoreRef = useRef(false);

  const controllerRef = useRef<AbortController | null>(null);
  const loadMoreControllerRef = useRef<AbortController | null>(null);
  // Bumped on every reload; a result whose captured generation != this is stale.
  const genRef = useRef(0);

  const load = useCallback((): void => {
    controllerRef.current?.abort();
    // A fresh page-1 load must win over any in-flight loadMore.
    loadMoreControllerRef.current?.abort();
    loadingMoreRef.current = false;
    setLoadingMore(false);

    const gen = ++genRef.current;
    const controller = new AbortController();
    controllerRef.current = controller;

    void listTrendMonitors(undefined, controller.signal)
      .then(({ monitors, nextPageToken }) => {
        if (controller.signal.aborted || gen !== genRef.current) return;
        setCore({ status: "data", monitors, nextPageToken });
      })
      .catch((err: unknown) => {
        if (controller.signal.aborted || gen !== genRef.current || isAbort(err)) {
          return;
        }
        setCore({ status: "error" });
      });
  }, []);

  const loadMore = useCallback((): void => {
    const current = coreRef.current;
    if (current.status !== "data") return;
    if (current.nextPageToken === "") return;
    if (loadingMoreRef.current) return;

    const gen = genRef.current;
    const token = current.nextPageToken;
    loadingMoreRef.current = true;
    setLoadingMore(true);

    const controller = new AbortController();
    loadMoreControllerRef.current = controller;

    void listTrendMonitors(token, controller.signal)
      .then(({ monitors, nextPageToken }) => {
        // Discard a result overtaken by a reload (generation bump / abort).
        if (controller.signal.aborted || gen !== genRef.current) return;
        loadingMoreRef.current = false;
        setLoadingMore(false);

        const prev = coreRef.current;
        if (prev.status !== "data") return;
        const seen = new Set(prev.monitors.map((m) => m.id));
        const appended = monitors.filter((m) => !seen.has(m.id));
        // Guard a bad svc contract: a page with zero net-new rows (empty, or all
        // already-loaded ids) must stop paging even if the server still handed
        // back a non-empty token — otherwise "Load more" loops forever appending
        // nothing. A page with SOME new rows keeps the server's token as usual.
        setCore({
          status: "data",
          monitors: [...prev.monitors, ...appended],
          nextPageToken: appended.length === 0 ? "" : nextPageToken,
        });
      })
      .catch((err: unknown) => {
        if (controller.signal.aborted || gen !== genRef.current || isAbort(err)) {
          return;
        }
        // A page-2 failure leaves the existing list intact — just stop loading.
        loadingMoreRef.current = false;
        setLoadingMore(false);
      });
  }, []);

  useEffect(() => {
    load();
    return () => {
      controllerRef.current?.abort();
      loadMoreControllerRef.current?.abort();
    };
  }, [load]);

  if (core.status === "data") {
    return {
      status: "data",
      monitors: core.monitors,
      nextPageToken: core.nextPageToken,
      loadingMore,
      loadMore,
      reload: load,
    };
  }
  if (core.status === "error") {
    return { status: "error", reload: load };
  }
  return { status: "loading", reload: load };
}


