/**
 * useWebSearch — Web-source search for the Monitor Search surface.
 *
 * #1133 shipped this as an honestly-idle stub (the discriminated-union
 * contract only, no backend). #1134 extends the BODY to a real, SUBMIT-
 * triggered fetch against POST /api/v1/monitor/search, without changing the
 * exported `state` discriminant — every call site that switches over `state`
 * keeps compiling.
 *
 * It mirrors useScrapePage's submit-triggered shape: it starts "idle" and only
 * moves once the user triggers `run(query)`. A single `controllerRef` always
 * points at the newest in-flight request — each run() aborts the prior
 * controller first (so an overlapping search cancels the one still in flight
 * and only the newest response wins), the effect cleanup aborts it on unmount,
 * and every settle handler bails when its own controller is aborted, so a
 * stale/cancelled response never reaches setState and an AbortError never
 * surfaces as an error state.
 *
 * The error state carries `kind`: a MonitorApiError with status 429 maps to
 * "throttle" (the provider is rate-limiting — informational, auto-retryable),
 * 503 (and any other failure) maps to "unavailable" (no response / not
 * configured — the danger path). It also carries `autoRetryCount` (how many
 * throttle failures have occurred in a row, so the throttle pane can cap its
 * automatic retries and stop hammering a still-throttled provider) and a
 * `retry()` that re-runs the last query in place.
 *
 * The raw server `message` is deliberately NOT surfaced: the UI shows generic,
 * non-leaking copy for every failure, so carrying the provider's detail here
 * would be dead state at best and a detail-leak vector at worst.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import {
  executeWebSearch,
  type WebResult,
  type WebSearchOptions,
} from "../api/search";
import { MonitorApiError } from "../api/client";

/** Which flavor of failure the error state represents. */
export type WebSearchErrorKind = "throttle" | "unavailable";

/** The submit-driven discriminant, before the shared controls are layered on. */
type WebSearchCore =
  | { readonly state: "idle" }
  | { readonly state: "loading" }
  | { readonly state: "data"; readonly results: WebResult[] }
  | {
      readonly state: "error";
      readonly kind: WebSearchErrorKind;
      /**
       * How many throttle failures have occurred in an unbroken streak (a
       * success or a non-throttle failure resets it to 0). The throttle pane
       * uses this to cap its automatic retries so it stops auto-firing at a
       * still-throttled provider and falls back to a manual "Try again".
       */
      readonly autoRetryCount: number;
      /** Re-run the last query in place — the error state's recovery action. */
      readonly retry: () => void;
    };

/** Controls available on EVERY state (mirrors useScrapePage). */
export interface WebSearchControls {
  /**
   * Trigger a web search for `query`, optionally scoped by filter/country/
   * locale `options`; supersedes any in-flight run. The options are captured
   * so `retry()` replays the exact same request.
   */
  readonly run: (query: string, options?: WebSearchOptions) => void;
  /** Return to the "idle" empty state, cancelling any in-flight run. */
  readonly reset: () => void;
}

export type WebSearchState = WebSearchCore & WebSearchControls;

/** Map a thrown error into the error-state's `kind`. */
function kindForError(err: unknown): WebSearchErrorKind {
  // 429 = provider throttling (auto-retryable, informational). Everything else
  // — 503, other statuses, and non-HTTP failures (network) — is "unavailable".
  return err instanceof MonitorApiError && err.status === 429
    ? "throttle"
    : "unavailable";
}

export function useWebSearch(): WebSearchState {
  const [state, setState] = useState<WebSearchCore>({ state: "idle" });

  // The newest in-flight request; every run() aborts whatever this points at
  // before replacing it, and the effect cleanup aborts it on unmount.
  const controllerRef = useRef<AbortController | null>(null);
  // The last request (query + its options), so retry() can re-run it in place
  // with the IDENTICAL filters/country/locale — a retry must never silently
  // drop the scope the user had applied.
  const lastQueryRef = useRef<{
    query: string;
    options: WebSearchOptions | undefined;
  } | null>(null);

  // How many throttle failures have occurred in an unbroken streak. Kept in a
  // ref (not state) so it survives the loading↔error remounts of the pane: a
  // success or non-throttle failure resets it, and the throttle pane caps its
  // automatic retries against the value carried on the error state.
  const throttleStreakRef = useRef(0);

  // retry() re-runs the last query. Held in a ref so the error variant's
  // `retry` is a stable reference and run()'s catch can reference it without a
  // dependency cycle.
  const retryRef = useRef<() => void>(() => undefined);

  const run = useCallback((query: string, options?: WebSearchOptions): void => {
    lastQueryRef.current = { query, options };

    // Cancel any request still in flight so an overlapping run wins and its
    // stale predecessor is dropped by the aborted-signal guards below.
    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;

    setState({ state: "loading" });

    void executeWebSearch(query, options, controller.signal)
      .then((response) => {
        // A newer run (or unmount) aborted this one — drop the stale response.
        if (controller.signal.aborted) return;
        throttleStreakRef.current = 0;
        setState({ state: "data", results: response.results });
      })
      .catch((err: unknown) => {
        // A cancellation (overlapping run or unmount) rejects this same
        // promise — normal teardown, never a real failure, so it must not
        // surface as an error state.
        if (
          controller.signal.aborted ||
          (err instanceof Error && err.name === "AbortError")
        ) {
          return;
        }
        const kind = kindForError(err);
        // Only a throttle extends the streak; any other failure (and every
        // success above) resets it, so the cap tracks CONSECUTIVE throttles.
        throttleStreakRef.current = kind === "throttle" ? throttleStreakRef.current + 1 : 0;
        setState({
          state: "error",
          kind,
          autoRetryCount: throttleStreakRef.current,
          retry: retryRef.current,
        });
      });
  }, []);

  const retry = useCallback((): void => {
    const last = lastQueryRef.current;
    if (last !== null) run(last.query, last.options);
  }, [run]);

  // Point retryRef at the current retry callback. Done in an effect so render
  // stays pure (no ref mutation during render); run()'s catch reads
  // retryRef.current only after settle, well after this effect has run.
  useEffect(() => {
    retryRef.current = retry;
  }, [retry]);

  const reset = useCallback((): void => {
    // Cancel any in-flight search so its late response can't clobber idle.
    controllerRef.current?.abort();
    controllerRef.current = null;
    setState({ state: "idle" });
  }, []);

  useEffect(() => {
    return () => {
      controllerRef.current?.abort();
    };
  }, []);

  return { ...state, run, reset };
}



