/**
 * useCollectedTrends — one monitor's collected-trends board state (#1144).
 * Fetches the board on mount and whenever `monitorId` changes; an in-flight
 * request is aborted on unmount or when the id changes, so switching monitors
 * can never resolve the old monitor's board over the new one.
 *
 * Discriminated union: the hook's RETURN VALUE is the union itself. Every
 * variant (loading / data / error) carries the SAME stable `reload()` callback,
 * so a caller can re-run the load from any state — including while the initial
 * request is still in flight. Mirrors useTrends (#1143).
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { type CollectedBoard, listCollectedTrends } from "../api/collectedTrends";

type BoardCore =
  | { readonly status: "loading" }
  | { readonly status: "data"; readonly board: CollectedBoard }
  | { readonly status: "error" };

export type CollectedTrendsState = (
  | { readonly status: "loading" }
  | { readonly status: "data"; readonly board: CollectedBoard }
  | { readonly status: "error" }
) & { readonly reload: () => void };

export function useCollectedTrends(monitorId: string): CollectedTrendsState {
  const [core, setCore] = useState<BoardCore>({ status: "loading" });
  const controllerRef = useRef<AbortController | null>(null);

  const load = useCallback((): void => {
    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;
    setCore({ status: "loading" });

    void listCollectedTrends(monitorId, controller.signal)
      .then((board) => {
        if (controller.signal.aborted) return;
        setCore({ status: "data", board });
      })
      .catch((err: unknown) => {
        if (
          controller.signal.aborted ||
          (err instanceof Error && err.name === "AbortError")
        ) {
          return;
        }
        setCore({ status: "error" });
      });
  }, [monitorId]);

  useEffect(() => {
    load();
    return () => controllerRef.current?.abort();
  }, [load]);

  if (core.status === "data") {
    return { status: "data", board: core.board, reload: load };
  }
  if (core.status === "error") {
    return { status: "error", reload: load };
  }
  return { status: "loading", reload: load };
}


