import { useEffect, useState } from "react";

/**
 * useMediaQuery — a matchMedia-backed viewport probe (#1139).
 *
 * Returns whether `query` currently matches and re-renders whenever it changes.
 * SSR / StrictMode safe:
 *  - the state is seeded from a lazy initializer, so the first paint already
 *    reflects the real viewport (no post-mount flash);
 *  - the effect re-syncs and subscribes to the `change` event, and its cleanup
 *    removes that listener, so a StrictMode double-mount never leaks a
 *    subscription;
 *  - when `matchMedia` is unavailable (SSR / very old jsdom) it degrades to
 *    `false` rather than throwing.
 *
 * Reads matchMedia in a hook (never `window.innerWidth` in render) so the value
 * stays reactive and jsdom-testable via a mocked `matchMedia`.
 */
function readMatch(query: string): boolean {
  if (typeof window.matchMedia !== "function") return false;
  return window.matchMedia(query).matches;
}

export function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState<boolean>(() => readMatch(query));

  useEffect(() => {
    if (typeof window.matchMedia !== "function") return;
    const mql = window.matchMedia(query);
    const update = (): void => setMatches(mql.matches);
    // Re-sync in case the viewport changed between the lazy init and this effect.
    update();
    mql.addEventListener("change", update);
    return () => mql.removeEventListener("change", update);
  }, [query]);

  return matches;
}


