/**
 * useMonitorDashboardStats — Monitor Dashboard quick-stat tiles state
 * (ticket #1128).
 *
 * Fetches MonitorDashboardStats on mount. A discriminated union — never a
 * loading/error/data object with optional fields — so the route can switch
 * exhaustively:
 *   - "loading" while the initial fetch is in flight
 *   - "data" once monitorDashboardStats() resolves
 *   - "error" on any fetch failure; carries `retry()` to re-fetch in place
 *
 * Mirrors range-mfe's useExerciseStats shape (state as the return value's own
 * discriminant, not a wrapped `{ state, refetch }`), per this ticket's
 * explicit contract.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { type MonitorDashboardStats, monitorDashboardStats } from "../api/dashboard";

/**
 * Fields available on EVERY state (ticket #1131). `refetch` lets the header's
 * Refresh action re-run the load from any state (loading/data/error), and
 * `refreshing` is true while a user-triggered refresh is in flight (distinct
 * from the initial "loading" state). Intersected into each union member so the
 * discriminant (`status`) is preserved.
 */
export interface MonitorDashboardStatsControls {
  /**
   * Re-run the stats fetch in place as a user-triggered refresh — keeps the
   * prior data on screen and drives `refreshing` while in flight. Available
   * from any state.
   */
  readonly refetch: () => void;
  /** True while a user-triggered refresh is in flight (not the first load). */
  readonly refreshing: boolean;
  /**
   * Re-run the stats fetch in place WITHOUT the refresh affordance (no
   * `refreshing` flag). Semantically the error state's recovery action, but
   * layered onto every state at the return boundary: discriminant narrowing
   * does not survive into deferred callbacks (e.g. an `act(() => …)` block),
   * so a caller that has already checked `status === "error"` still needs
   * `retry` present on the un-narrowed type to invoke it there. The narrow
   * internal core keeps `retry` on the `error` variant alone; this control is
   * the public, always-reachable handle to the same load.
   */
  readonly retry: () => void;
}

/**
 * The load-driven discriminant, before the shared controls are layered on. The
 * hook's internal state is this narrower shape; the public state (below) adds
 * the controls at the return boundary.
 */
type MonitorDashboardStatsCore =
  | { readonly status: "loading" }
  | { readonly status: "data"; readonly stats: MonitorDashboardStats }
  | { readonly status: "error"; readonly retry: () => void };

/**
 * Public hook state: the load discriminant intersected with the shared
 * controls, so `refetch`/`refreshing` are available across every state while
 * `status` stays the exhaustive discriminant. (Intersection distributes over
 * the union, so each member keeps its own discriminant.)
 */
export type MonitorDashboardStatsState = MonitorDashboardStatsCore &
  MonitorDashboardStatsControls;

/**
 * useMonitorDashboardStats — fetches the quick-stat DTO on mount.
 *
 * The hook's return value IS the discriminated union (no separate
 * `{ state, refetch }` wrapper): "loading" while the fetch is in flight,
 * "data" on success, "error" (carrying `retry`) on any failure. `retry`
 * re-runs the load in place — it does not flash back to "loading" first, so
 * a failed retry that succeeds transitions straight from "error" to "data".
 *
 * Both the mount fetch and any in-place refetch are aborted on unmount via
 * the AbortController threaded into monitorDashboardStats(). A single
 * `controllerRef` always points at the LATEST in-flight request, which drives
 * three related behaviors (ticket #1131):
 *   - each `load()` aborts the prior controller first, so an overlapping
 *     refetch cancels the one still in flight and only the newest response
 *     wins;
 *   - the effect cleanup aborts `controllerRef.current` (the newest request),
 *     not a controller captured at mount time, so unmounting mid-refetch
 *     cancels the refetch too;
 *   - every settle handler bails when its own controller's signal is aborted,
 *     so a stale/cancelled response never reaches setState.
 *
 * `load()` never sets status:"loading" — the initial useState value already
 * is, and a refetch must keep the prior data on screen. A user-triggered
 * refetch instead flips the separate `refreshing` flag while it is in flight;
 * the mount fetch and error `retry` leave it untouched.
 */
export function useMonitorDashboardStats(): MonitorDashboardStatsState {
  const [state, setState] = useState<MonitorDashboardStatsCore>({
    status: "loading",
  });
  const [refreshing, setRefreshing] = useState(false);

  // The newest in-flight request. Every load() aborts whatever this points at
  // before replacing it, and the effect cleanup aborts it on unmount.
  const controllerRef = useRef<AbortController | null>(null);

  const load = useCallback(
    (opts?: { readonly refresh?: boolean }): AbortController => {
      const refresh = opts?.refresh ?? false;

      // Cancel any request still in flight so an overlapping load wins and its
      // stale predecessor is dropped by the aborted-signal guards below.
      controllerRef.current?.abort();

      const controller = new AbortController();
      controllerRef.current = controller;

      // Set the busy flag deterministically for THIS load: a user-triggered
      // refresh drives `refreshing` true (keeps prior data visible instead of
      // flashing back to the loading skeleton), while any non-refresh load
      // (mount, error `retry`, error-recovery) drives it false. Crucially,
      // clearing it here means a non-refresh load that SUPERSEDES an in-flight
      // refresh also clears that refresh's busy state — the superseded refetch
      // aborts and its settle handler bails at the aborted-signal guard before
      // it could ever call setRefreshing(false), so without this the flag would
      // stick true forever (Refresh permanently aria-busy + disabled).
      setRefreshing(refresh);

      void monitorDashboardStats(controller.signal)
        .then((stats) => {
          // A newer load (or unmount) aborted this one — its response is
          // stale, so drop it without touching state.
          if (controller.signal.aborted) return;
          setState({ status: "data", stats });
          if (refresh) setRefreshing(false);
        })
        .catch((err: unknown) => {
          // The effect-cleanup abort() on unmount, or an overlapping load's
          // abort(), rejects this same promise — that is a normal
          // cancellation, not a real fetch failure, so it must never surface
          // as status:"error". Guard on the controller's own signal first
          // (the authoritative source), and fall back to the error's name for
          // a signal that may have been replaced/reconstructed.
          if (
            controller.signal.aborted ||
            (err instanceof Error && err.name === "AbortError")
          ) {
            return;
          }
          setState({ status: "error", retry: load });
          if (refresh) setRefreshing(false);
        });
      return controller;
    },
    [],
  );

  useEffect(() => {
    load();
    return () => {
      // Abort the NEWEST request (mount fetch or any later refetch), not the
      // controller captured when this effect first ran.
      controllerRef.current?.abort();
    };
  }, [load]);

  // The header's Refresh action: re-run the load in place as a user-triggered
  // refresh (keeps prior data + drives `refreshing`), callable from any state.
  const refetch = useCallback((): void => {
    load({ refresh: true });
  }, [load]);

  // Error-state recovery: re-run the load in place without the refresh
  // affordance. Same load the error variant's `retry` points at, exposed on
  // every state at the return boundary (see the control's doc comment).
  const retry = useCallback((): void => {
    load();
  }, [load]);

  return { ...state, refetch, refreshing, retry };
}


