/**
 * useSaveToFiles — Save-to-Files submit state (ticket #1139).
 *
 * A SUBMIT-triggered hook mirroring useSummarize: it starts "idle" and only
 * moves once the caller triggers `run()`. A discriminated union so the modal can
 * switch exhaustively:
 *   - "idle"   before any save
 *   - "saving" while the save is in flight
 *   - "saved"  once saveToFiles() resolves (carries the created documentId)
 *   - "error"  on any failure; carries `retry()` to re-run the last save
 *
 * `run(body)` triggers a save; `reset()` returns to "idle"; `retry()` re-runs
 * the LAST body. All three are layered onto every state at the return boundary
 * so a caller that has narrowed `status` can still reach them.
 *
 * A single `controllerRef` always points at the newest in-flight request: each
 * run() aborts the prior controller first (so an overlapping save cancels the
 * one still in flight and only the newest response wins), the effect cleanup
 * aborts it on unmount, and every settle handler bails when its own controller
 * is aborted — so a stale/cancelled response never reaches setState and an
 * AbortError never surfaces as status:"error".
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { type SaveToFilesBody, saveToFiles } from "../api/saveToFiles";

/** The submit-driven discriminant, before the shared controls are layered on. */
type SaveCore =
  | { readonly status: "idle" }
  | { readonly status: "saving" }
  | { readonly status: "saved"; readonly documentId: string }
  | { readonly status: "error"; readonly retry: () => void };

/** Controls available on EVERY state (see useSummarize). */
export interface SaveToFilesControls {
  /** Save `body`; supersedes any in-flight run. */
  readonly run: (body: SaveToFilesBody) => void;
  /** Return to the "idle" state, cancelling any in-flight run. */
  readonly reset: () => void;
  /**
   * Re-run the LAST save (same body). Semantically the error state's recovery
   * action — also exposed on every state so a caller that has already narrowed
   * `status === "error"` can invoke it from a deferred callback where the
   * discriminant no longer narrows.
   */
  readonly retry: () => void;
}

export type MonitorSaveToFilesState = SaveCore & SaveToFilesControls;

export function useSaveToFiles(): MonitorSaveToFilesState {
  const [state, setState] = useState<SaveCore>({ status: "idle" });

  // The newest in-flight request; every run() aborts whatever this points at
  // before replacing it, and the effect cleanup aborts it on unmount.
  const controllerRef = useRef<AbortController | null>(null);
  // The last requested body, so retry() can re-run it in place.
